import React, { forwardRef } from 'react';
import { type Types } from '@fiverr-private/theme';
import Layout from '../../Layout';

const WrapItem = forwardRef<HTMLElement, Types.FlexLayoutProps>(
  ({ children, dataTrackTag = 'wrap_item', ...restProps }: Types.FlexLayoutProps, ref) => (
    <Layout ref={ref} dataTrackTag={dataTrackTag} {...restProps}>
      {children}
    </Layout>
  )
);

WrapItem.displayName = 'WrapItem';

export default WrapItem;
